+.product-rating {
+    margin: 0 0 0.4rem;
+    color: #ffc107;
+    font-size: 1rem;
+    letter-spacing: 1px;
+}
+
+.badge-out-of-stock {
+    display: inline-block;
+    background: #dc3545;
+    color: #fff;
+    font-size: 0.75rem;
+    padding: 0.15rem 0.5rem;
+    border-radius: 4px;
+    margin-bottom: 0.4rem;
+}
+
+.btn-add-cart {
+    width: 100%;
+    background: #0d6efd;
+    color: #fff;
+    margin-top: 0.4rem;
+}
+
+.btn-add-cart:hover:not(:disabled) {
+    background: #0a58ca;
+}
+
+/* Pagination */
+.catalog-pagination {
+    display: flex;
+    justify-content: center;
+    align-items: center;
+    gap: 0.35rem;
+    margin-top: 1.5rem;
+    flex-wrap: wrap;
+}
+
+.btn-page {
+    min-width: 2.5rem;
+    padding: 0.4rem 0.75rem;
+    background: #fff;
+    border: 1px solid #dee2e6;
+    color: #212529;
+    font-size: 0.9rem;
+}
+
+.btn-page:hover:not(:disabled):not(.active) {
+    background: #e9ecef;
+}
+
+.btn-page.active {
+    background: #0d6efd;
+    color: #fff;
+    border-color: #0d6efd;
+}
+
+/* State displays */
+.catalog-loading,
+.catalog-empty,
+.catalog-error {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    justify-content: center;
+    padding: 3rem 1rem;
+    text-align: center;
+    color: #6c757d;
+    min-height: 300px;
+}
+
+.catalog-error {
+    color: #dc3545;
+}
+
+.catalog-error .btn {
+    margin-top: 0.75rem;
+}
+
+/* Responsive */
+@media (max-width: 768px) {
+    .catalog-container {
+        flex-direction: column;
+    }
+
+    .catalog-sidebar {
+        flex: none;
+        width: 100%;
+        position: static;
+    }
+}
+

